			dw kw_add, tmp0, var_sum3_z, var_sum3_sum3
			dw p_sum3_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if7_e_go:			ld sp, if7_e
			jp ntc_xn
if8_e_go:			ld sp, if8_e
			ret
if9_e_go:			ld sp, if9_e
			jp ntc_xn
do10_t_go:			ld sp, do10_t
			jp ntc_xn
sel13_e_go:			ld sp, sel13_e
			jp ntc_xn
sel14_e_go:			ld sp, sel14_e
			jp ntc_xn

p_chk_n_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk_n
			jp ntc_xn
p_chk_n_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chk_c:		; call chk (turbo)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			ret
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			ret
p_chks_c:		; call chks (normal)
			pop hl			; got
			ld de, var_chks_got
			ld b, 40
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 40
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
